export const normalizeTech = (name: string) => name.toLowerCase().replace(/[^a-z0-9]/g, '')

export const findTechIcon = (name: string): TechIconDef | undefined => {
  const key = aliases[normalizeTech(name)]
  return key ? techIcons[key] : undefined
}

// Canonical id for a technology, so "Vue.js" and "Vue.js 3" count as the same thing.
export const techKey = (name: string) => aliases[normalizeTech(name)] ?? normalizeTech(name)
